    "subtitle": "ภาพบรรยากาศในงานศพ (Atmosphere & Candid Moments) ไม่ใช่แค่การถ่ายภาพคนมาร่วมงาน แต่คือการบันทึก \"สายสัมพันธ์ ความรัก และอารมณ์ความรู้สึก\" ของการจากไปชั่วนิรันดร์",
